            if not data_in:
                if before + after in '|-' or before + after == '-|':
                    if before[0] in '[0123456789]' or after[0] in '[0123456789]':
                        digit = after - before + i - idx
                        if digit >= 0 and digit <= 9:
                            data_in = True
                            joltage = i - idx - 1
                        else:
                            return "false"
                        if idx == 0:
                            stack.append(digit)
                    elif before + after in ',.,[ ]':
                        continue
                    else:
                        before_data = True
                        break
                elif before == after or before == after + '_':
                    continue
                elif before == after + '-' or (before == '-' and after == ')]'):
                    if before == ']' or after != '[':
                        char += '|'
                        prefix = result_to_binary(pre, post)
                        temp = [prefix, stack]
                        stack = []
                        if temp == [(' ', ['9', '0']), []]:
                            return '9'

                        return result_to_binary(pre, temp[0])
            else:
                previous = stack[-2] if stack else 0
                if before[0] in '[0123456789]' or after[0] in '[0123456789]' or after in '|-' or after == '-|':
                    digit = int(name[idx])
