from math import factorial
from collections import defaultdict

MOD = 998244353

def fmat_mul(fmat1, fmat2):
    n = len(fmat1)
    res = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                res[i][j] += (fmat1[i][k] * fmat2[k][j]) % MOD
                res[i][j] %= MOD
    return res

def mat_power(mat, exp):
    n = len(mat)
    res = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    while exp:
        if exp & 1:
            res = fmat_mul(res, mat)
        mat = fmat_mul(mat, mat)
        exp >>= 1
    return res

def LNDS(X):
    return mat_power([[1], [0]], X).tolist()[0][0]

def F(A, B):
    return max(LNDS(A), LNDS(B))

def solution(N):
    # Store the F(A, B) for each test case
    F_values = defaultdict(lambda: 0)
    for _ in range(N):
        N1 = bin(input().strip()).count("1")  # Number of '1's in the first binary array A
        N2 = bin(input().strip()).count("1")  # Number of '1's in the second binary array B
        if N1 != N2:
            print(0)  # If not equal, no way to match, so F(ab) = 0
            return
        F_values[bin(N1).count("1")] = 1  # F(ab) = 1 for equal number of 1's

    # Calculate S(N)
    S = sum([2 ** n for n in range(N)])
    max_F = 0
    for num in range(N):
        max_F = max(max_F, F(F_values[num], F_values[S - num]))
    result = 2 * max_F % MOD
    return MOD if result >= MOD else result

T = int(input())
for _ in range(T):
    N = int(input())
    result = solution(N)
    print(result)
