def compute_combinations(n, m):
    if m > n:
        return 0
    else:
        return pow(2, n, MOD) * pow(n, m, MOD) // pow(m, MOD, MOD) % MOD

class QueryProcessor:
    def __init__(self, size):
        self.size = size
        self.combinations = [[0, 0] for _ in range(size + 1)]
        self.cache = {}

    def process_query(self, l, r, k):
        if l > r:
            return 0
        min_max = min(l, r)
        max_min = max(l, r)
        if (l, r, k) in self.cache:
            return self.cache[(l, r, k)]

        combinations = self.combinations[min_max]
        current_combinations = combinations[r] + 1
        total_sum = 1 + current_combinations

        for ll, lr in combinations[l - 1]:
            if ll == r:
                continue
            rr = r - ll + 1
            index = total_sum + k * (rr - 1) // rr
            modifier = 1 << ll
            total_sum = (total_sum + modifier * current_combinations) % MOD

        self.cache[(l, r, k)] = total_sum

        return total_sum % MOD

