def find_configurations(N, G):
    G = set(G)
    unlockable_routes = {u: sorted([v for v in G if (u, v) not in U and (v, u) not in U]) for u in G}
    max_route_id = max(u for u, _ in G)
    configurations = 0

    for rounds in itertools.combinations_with_replacement(range(max_route_id), N - 2):
        lockable_routes = defaultdict(set)
        for u, G in unlockable_routes.items():
            key = reduce(gcd, G)
            lockable_routes[key].add(u)

