        for slate in permutations(rounds):
            s = set(slate)
            blue, red = next(iter(s)), next(n for n in s if n != next(iter(s)))
            for u, v in s:
                tmp[v].add((u, v, slate))
                if (u, v) in G and (v, u) not in G:
                    lockable_routes[u].remove(v)
                if (u, v) not in G and (v, u) in G:
                    lockable_routes[v].remove(u)

        for s in (r for r in lockable_routes.keys() if len(set(r)) != len(r)):
            lockable_routes[s].update(reset(0, s, lockable_routes[s]))

        for k, v in lockable_routes.items():
            ts = tuple(sorted(x[1] for x in sorted(v, key=lambda x: hash(x))))
            if ts in tmp:
                configurations -= len(v) - 1 - tmp[ts]
            lockable_routes[k] -= set(ts)

    return configurations % (10**9 + 7)

def reset(n, routes, routes_locked_by):
    d = defaultdict(set)

    for u, v in routes:
        if u == n and (u, v) in routes_locked_by:
            nodes = routes_locked_by[(u, v)]
            nodes.discard(v)
            for x in (t for t in nodes if hash(t) not in d):
                d[hash(x)].add((hash(u), hash(v), x))

    # delete locks
    for x, y in routes_locked_by:
        routes_locked_by[(x, y)].discard(v)

    return d[0]
