            root[find(x)] = find(root[x])
        return root[x]

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                root[root_y] = root_x
                tree_size[root_x] += tree_size[root_y]
            else:
                root[root_x] = root_y
                tree_size[root_y] += tree_size[root_x]
            if rank[root_x] == rank[root_y]:
                rank[root_y] += 1

    for i in range(len(edges)):
        if len(tree[edges[i][0]]) < 2 and len(tree[edges[i][1]]) < 2:
            union(edges[i][0], edges[i][1])
        if len(tree[edges[i][0]]) == 2:
            union(edges[i][1], edges[i][0])
        if len(tree[edges[i][1]]) == 2:
            union(edges[i][0], edges[i][1])
        for edge in graph[edges[i][0]]:
            if edge not in edges[i][1] and find(edge[0]) != find(edge[1]):
                tree_size[find(edge[0])] += 1
                tree_size[find(edge[1])] += 1
            tree[edges[i][0]].append(edge)
        for edge in graph[edges[i][1]]:
            if edge not in edges[i][0] and find(edge[0]) != find(edge[1]):
                tree_size[find(edge[0])] += 1
                tree_size[find(edge[1])] += 1
            tree[edges[i][1]].append(edge)

    cycles = []
    current = 0
    while current < vertices - 1:
        edges_found = False
        minimal_edge = (vertices, 0)
        for edge in edges[current]:
            if edge[0] == current + 1 and tree_size[find(edge[0])] > 2:
                edges_found = True
                edges[current] = edge
                current = edge[1]
                minimal_edge = (vertices, 0)
                break
        if not edges_found:
            if (vertices - current, vertices - current) not in edges:
                current += 1
                continue
        edge = edges.pop(current)
        edges[current] = (edge[0], vertices)
        edges.pop(current)
        edge = edges.pop(current)
        edges[current] = (vertices, edge[1] - 1)
        edge = edges.pop(current)
        current = edge[1]
    for edge in edges:
        if edge[1] < edge[0]:
            cycles.append((edge[1], edge[1], edge[1]))   
        else:
            cycles.append((edge[1] + 1, edge[1], edge[1])) 
    k = len(cycles)
    for i in range(2, vertices + 1):
        cycles.append((i, find(i), i))
    return k, cycles

