        total_weirdness += recur_weirdness(array, i, j)

    print(total_weirdness)

def recur_weirdness(array, L, R):
    weirdness_values = defaultdict(int)
    weirdness_values[L] += 1

    for i in range(L, R + 1):
        if array[i] in weirdness_values:
            weirdness_values[array[i]] += 1
        for k in range(L + 1, i + 1):
            if array[k] == array[i] and array[k] not in weirdness_values:
                weirdness_values[array[k]] += 1

    return sum(val != n for val in weirdness_values.values())
