def dp(a, b, i, memo={}):
    if i >= n:
        return 0
    if (a, b, i) in memo:
        return memo[(a, b, i)]
    res = 0
    for j in range(n):
        for k in range(n):
            if (a[k] or j) != b[i] and (b[j] or i) != a[i]:
                res += (
                    max(0, dp(j + 1, k + 1, i + 1, memo) - dp(j + 1, k, i + 1, memo))
                ) % MOD
    t = set()
    for j in range(n):
        if a[j] != b[i]:
            t.add((j, ln_dist(a[j] + b[i])))
    res -= min(1, sum([dp(j[0], i) for j in t]))
    memo[(a, b, i)] = res
    return res

