from collections import defaultdict

def find_smallest_interesting_option(s, t, q):
    n = len(s)
    dp = defaultdict(list)
    for i in range(n + 1):
        dp[i].append((1, -1))

    # Helper function to merge dp values
    def merge(a, b):
        for char, val in b.items():
            if char in a:
                a[char], small_index = min(a[char], val), small_index if a[char] < val else -1
            else:
                a[char] = val
        return a

    # Main function
    for i in range(1, n + 1):
        dp[i] = merge(dp[i - 1], [(1, i)])

    # Answer function
    def answer(l, r, k, x, y):
        return dp[r + 1].get((x, y), -1)

    for _ in range(q):
        l, r, k, x, y = map(int, input().split())
        print(answer(l - 1, r, k, x, y))

