def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def circumcircle_points(slope, axis, off, n):
    divs = bottom_half(slope, 0)
    for i in range(n + 1):
        t = (n - i) / (n - 1)
        p = *(bottom_half(slope, i),)
        x = (t * off + (1 - t) * p[off]) * divs
        y = (t * axis + (1 - t) * p[axis]) * divs
        if x >= 0 and y >= 0:
            yield x, y

def bottom_half(slope, denom):
    denom = gcd(slope, denom)
    slope *= -1
    denom *= -1
    cand = lambda a:((-1)**a) * slope / denom
    return [-cand(d) for d in range(1, denom + 1)]

