from collections import deque

def solve(n, k):
    if n == 1:
        return deque([1])

    if n >= 6 and k >= 8:
        return deque([-1])

    # Initialize lists to store decompositions and mapped permutations
    decompositions = []
    mapped_perms = [None] * 100  # Assuming 100 as the maximum length of a permutation for this problem

    for i in range(1, n + 1):
        if len(decompositions) > 0 and decompositions[-1][0] + 1 < i:
            mapped_perms[i] = decompositions[-1][1][-1]
            while len(decompositions) > 0 and decompositions[-1][0] == i - len(decompositions[-1][1]):
                decompositions.pop()
            decompositions[-1][1].append(i)
        else:
            mapped_perms[i] = i
            decompositions.append([i, deque([i])])

    # Transform permutations based on the decompositions
    result = []
    for i in range(1, n + 1):
        if i != mapped_perms[i]:
            result.append(mapped_perms[i])
        else:
            rotation = deque(decompositions[-1][1])
            while len(rotation) > 0 and mapped_perms[i] == rotation.pop():
                size = len(rotation)
                rotation = rotation[size:] + rotation[:size - 1]
            result.append(mapped_perms[i])
            decompositions.pop()

    # Generate the k-th good permutation
    value = k
    for i in range(n):
        for j in range(100):
            if mapped_perms[j] == value:
                result.insert(i, j)
                value += 100
                break

    return deque(result)

