def solve(n, queries):
    results = []
    gates = [0] * (1 << n)
    queried = [False] * (1 << n)

    for q in queries:
        planet_a, planet_b = q
        if not queried[planet_a]:
            queried[planet_a] = True
            if planet_b < planet_a:
                planet_b += (1 << n)
            gates[planet_a] = 1
            for base in range(n):
                if gates[planet_b & ~(1 << base)]:
                    gates[planet_a] |= (1 << base)

    for planet_a, planet_b in queries:
        planet_a += (1 << n)
        if planet_b < planet_a:
            planet_b += (1 << n)
        if gates[planet_a] & gates[planet_b]:
            results.append("1")
        else:
            results.append("0")

    return results

